#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public class BDirectAttackBuffTests {
  const string Root="D:/Project/LASTRAIL/",QA=Root+"QA/CombatBMigration-20261002/AttackBuffConsumer/";
  static JObject Owned()=>(JObject)JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/c3-owned-profile-observed-sql-test-20261001.json"))["profile"];
  static CombatDefinitionIndex Definition()=>CombatDefinitionIntake.Read(JObject.Parse(File.ReadAllText(Root+"QA/CommanderS1-20260922/c3-definition-intake-20261001.json")));
  static BCarriageBuffDefinitions Defs(){string j=File.ReadAllText(Root+"QA/CombatBMigration-20261002/BuffConsumer/original-definitions.json");using var sha=SHA256.Create();return new BCarriageBuffDefinitions(j,BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(j))).Replace("-","").ToLowerInvariant());}
  static BCombatFormation Formation(int count=1)=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,Enumerable.Range(0,count).Select(i=>new BCombatSlot("car"+i,i==0?"op_mira":null)));
  static JObject Packet(int count=1){var p=JObject.Parse(File.ReadAllText(Root+"QA/CombatBMigration-20261002/AttackConsumer/local-original-input.json"));p["formation"]=Formation(count).Capture();var rows=(JArray)p["entities"];var car=rows.Single(x=>(string)x["id"]=="car0");for(int n=1;n<count;n++){var c=(JObject)car.DeepClone();c["id"]="car"+n;c["definitionId"]="LOCAL_ORIGINAL_car"+n;c["slot"]=n;rows.Add(c);var g=(JObject)((JArray)p["geometry"]).Single(x=>(string)x["sourceId"]=="enemy"&&(string)x["targetId"]=="car0").DeepClone();g["targetId"]="car"+n;g["targetSlot"]=n;((JArray)p["geometry"]).Add(g);}return p;}
  static JObject Entity(JObject p,string id)=>(JObject)((JArray)p["entities"]).Single(e=>(string)e["id"]==id);
  static JObject Q(long n,long d=1)=>new JObject{["numerator"]=n.ToString(),["denominator"]=d.ToString()};
  static BDirectAttackInput Input(JObject packet=null){packet=packet??Packet();((JArray)packet["sourceEvidence"]).Add(new JObject{["sourceId"]="LOCAL_COMPOSITION_TRIAL_BOUNDARY_NOT_OPERATING_ENEMY_OR_B_BASE",["sha256"]=BDirectAttackInput.Digest(packet).Substring(7)});var o=Owned();return new BDirectAttackInput(packet,BDirectAttackInput.Digest(packet),Formation(((JArray)packet["formation"]["slots"]).Count),o,BDirectAttackInput.Digest(o),Definition());}
  static JObject Candidate(string type="BCB01",int rank=5,int count=1)=>(JObject)((JArray)JObject.Parse(File.ReadAllText(QA+"original-candidates.json"))["candidates"]).Single(x=>(string)x["name"]==type+"_R"+rank+"_SLOTS"+count)["departure"].DeepClone();
  static JObject BindingPacket(BDirectAttackInput input,string type="BCB01",int rank=5,string category="ENEMY"){
   int count=input.Formation.Slots.Count;var d=Candidate(type,rank,count);return new JObject{["version"]=BDirectAttackBuffBinding.Version,["provenance"]="BOUNDED_LOCAL_NOT_FULL_RUN",["attackInputHash"]=input.OriginalHash,["definitionHash"]=Defs().Hash,["departure"]=d,
    ["initial"]=new JObject{["contextId"]="LOCAL_ATTACK_BUFF_"+type+"_R"+rank+"_"+count,["mode"]="EXTERIOR",["cars"]=new JArray(((JArray)d["cars"]).Select(c=>new JObject{["slot"]=c["slot"].DeepClone(),["body"]="NORMAL",["actor"]=(string)c["occupant"]["kind"]=="CARGO"?"ABSENT":"UP"}))},
    ["targetCategories"]=new JArray(new JObject{["targetId"]="enemy",["category"]=category})};}
  static BDirectAttackBuffBinding Binding(JObject packet=null,string type="BCB01",int rank=5,string category="ENEMY"){var i=Input(packet);var b=BindingPacket(i,type,rank,category);return new BDirectAttackBuffBinding(i,Defs(),b,BDirectAttackInput.Digest(b));}
  static BDirectAttackBuffSession Session(JObject packet=null,string type="BCB01",int rank=5,string category="ENEMY",int capacity=10000)=>new BDirectAttackBuffSession(Binding(packet,type,rank,category),capacity);
  static void Same(JToken a,JToken b)=>Assert.IsTrue(JToken.DeepEquals(a,b),"expected "+a+" actual "+b);
  static long Bps(BDirectAttackBuffReceipt r)=>(long)r.BuffSource["damageBps"];
  [Test] public void ActualOwnedMiraStatPassesAcceptedSourceBeforeNumericDefenseAndHp(){var b=Binding();var s=new BDirectAttackBuffSession(b,10000);var r=s.ApplyBasicImpact("hit","op_mira","enemy",0);Assert.AreEqual(3000,Bps(r));Assert.AreEqual(41,r.Attack.BeforeShield);Same(Q(41613,1000),r.Attack.Calculation["exact"]);Assert.AreEqual(659,s.Hp("enemy"));Assert.AreEqual(1520,s.Hp("op_mira"));Assert.AreEqual(0,(long)r.BuffSource["operatingRevision"]);Assert.AreEqual(1,(int)s.Capacity()["recorded"]);File.WriteAllText(QA+"local-original-binding.json",b.Capture().ToString());}
  [Test] public void NonBonusOriginalPathKeepsExactResultAndExistingPeriod(){var b=Binding(type:"BCB02");var old=new BDirectAttackSession(b.Attack,10000);var expected=old.ApplyBasicImpact("hit","op_mira","enemy",0);var s=new BDirectAttackBuffSession(b,10000);var r=s.ApplyBasicImpact("hit","op_mira","enemy",0);Same(expected.Calculation,r.Attack.Calculation);Assert.AreEqual(expected.Hp.HpAfter,r.Attack.Hp.HpAfter);Assert.AreEqual(0,Bps(r));var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>s.ApplyBasicImpact("early","op_mira","enemy",0));Same(before,s.Capture());}
  [TestCase("BCB01",1,"STRUCTURE",3000,41)][TestCase("BCB01",5,"STRUCTURE",5000,48)][TestCase("BCB04",1,"STRUCTURE",3500,43)][TestCase("BCB04",5,"STRUCTURE",5500,49)]
  [TestCase("BCB04",5,"ATTACHED",3000,41)][TestCase("BCB04",5,"CLIMBING",3000,41)][TestCase("BCB07",5,"ENEMY_TRAIN_PART",3500,43)]
  public void ActualRankAndOneTargetCategoryProduceSingleC(string type,int rank,string category,int bps,int amount){var s=Session(type:type,rank:rank,category:category);var r=s.ApplyBasicImpact("hit","op_mira","enemy",0);Assert.AreEqual(bps,Bps(r));Assert.AreEqual(amount,r.Attack.BeforeShield);Assert.AreEqual(700-amount,s.Hp("enemy"));}
  [Test] public void ShieldAbsorptionAndOriginalEquipmentGroupAreAppliedOnlyOnce(){var p=Packet();((JArray)Entity(p,"op_mira")["attackSources"]).Add(new JObject{["sourceId"]="original:atk",["ownerId"]="op_mira",["group"]="EQUIPMENT_ATK",["valueBps"]=1000});((JArray)p["initialShields"]).Add(new JObject{["targetId"]="enemy",["sourceEntity"]="enemy",["sourceAbility"]="original_shield",["effectIndex"]=0,["amount"]=10,["expiryTick"]=10});var s=Session(p,category:"STRUCTURE");var r=s.ApplyBasicImpact("hit","op_mira","enemy",0);Same(Q(105633,2000),r.Attack.Calculation["exact"]);Assert.AreEqual(52,r.Attack.BeforeShield);Assert.AreEqual(10,r.Attack.Hp.Absorbed);Assert.AreEqual(42,r.Attack.Hp.HpLoss);Assert.AreEqual(658,s.Hp("enemy"));}
  [Test] public void FlatCarriageBuffPrecedesOriginalPercentExactlyOnce(){var p=Packet();((JArray)Entity(p,"car0")["defenseSources"]).Add(new JObject{["sourceId"]="original:def",["ownerId"]="car0",["group"]="EQUIPMENT_DEF",["valueBps"]=5000});var s=Session(p,type:"BCB06");var r=s.ApplyBasicImpact("incoming","enemy","car0",0);Assert.IsNull(r.BuffSource);Same(Q(561,2),r.Attack.Calculation["effectiveDefense"]);Assert.AreEqual(31,r.Attack.BeforeShield);Assert.AreEqual(31,r.Attack.Hp.HpLoss);Assert.AreEqual(9,r.Attack.Hp.TrainHpLoss);Assert.AreEqual(969,s.Hp("car0"));}
  [Test] public void OperatorAndTrainDefenseRecipientsStayIndependent(){var s=Session(type:"BCB06");var r=s.ApplyBasicImpact("incoming","enemy","op_mira",0);Assert.AreEqual(171,(long)r.Attack.Calculation["effectiveDefense"]["numerator"]);Assert.AreEqual(34,r.Attack.Hp.HpLoss);Assert.AreEqual(0,r.Attack.Hp.TrainHpLoss);var train=Session(type:"BCB06");var tr=train.ApplyBasicImpact("train-hit","enemy","train",0);Assert.AreEqual(111,(long)tr.Attack.Calculation["effectiveDefense"]["numerator"]);Assert.AreEqual(36,tr.Attack.Hp.HpLoss);Assert.AreEqual(0,tr.Attack.Hp.TransferToTrain);}
  [Test] public void BreakingHitCapturesOldDefenseThenLivingMiraLosesOnlyNewBonus(){var p=Packet();Entity(p,"car0")["maxHp"]=20;var s=Session(p,type:"BCB06",category:"STRUCTURE");var hit=s.ApplyBasicImpact("break","enemy","car0",0);Assert.AreEqual(187,(long)hit.Attack.Calculation["effectiveDefense"]["numerator"]);Assert.AreEqual(33,hit.Attack.BeforeShield);Assert.AreEqual(20,hit.Attack.Hp.HpLoss);Assert.AreEqual(6,hit.Attack.Hp.TrainHpLoss);Assert.IsTrue(hit.Attack.Hp.CarriageDown);Assert.AreEqual(1520,s.Hp("op_mira"));var r=s.ApplyBasicImpact("living","op_mira","enemy",0);Assert.AreEqual(0,Bps(r));Assert.AreEqual(32,r.Attack.BeforeShield);Assert.AreEqual(668,s.Hp("enemy"));Assert.AreEqual(1,(long)r.BuffSource["operatingRevision"]);}
  [Test] public void AcceptedOriginalReceiptSurvivesLaterBreakAndRestore(){var p=Packet();Entity(p,"car0")["maxHp"]=20;var b=Binding(p,category:"STRUCTURE");var s=new BDirectAttackBuffSession(b,10000);var original=s.ApplyBasicImpact("hit","op_mira","enemy",0);s.ApplyBasicImpact("break","enemy","car0",0);Assert.AreSame(original,s.ApplyBasicImpact("hit","op_mira","enemy",0));Assert.AreEqual(48,original.Attack.BeforeShield);var restored=BDirectAttackBuffSession.Restore(s.Capture(),b,10000);var replay=restored.ApplyBasicImpact("hit","op_mira","enemy",0);Same(original.BuffSource,replay.BuffSource);Same(original.Attack.Calculation,replay.Attack.Calculation);Same(s.Capture(),restored.Capture());var next=restored.AdvanceAndApplyBasicImpact("living","op_mira","enemy",1800,18000000,1800);Assert.AreEqual(0,Bps(next));Assert.AreEqual(32,next.Attack.BeforeShield);}
  [Test] public void DownReportsActorOnlyAndRejectsNewActionAtomically(){var p=Packet();Entity(p,"enemy")["attack"]=Q(4000);var s=Session(p,type:"BCB06");var hit=s.ApplyBasicImpact("down","enemy","op_mira",0);Assert.AreEqual(1520,hit.Attack.Hp.HpLoss);Assert.AreEqual(0,s.Hp("op_mira"));var m=BCarriageBuffModel.Restore(s.BuffSnapshot(),Defs());Assert.AreEqual(0,m.Defense(0,"OPERATOR"));Assert.AreEqual(100,m.Defense(0,"BODY"));var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>s.AdvanceAndApplyBasicImpact("down-action","op_mira","enemy",1800,18000000,1800));Same(before,s.Capture());}
  [Test] public void DirectTrainDefeatKeepsOriginalReplayButRejectsFreshLivingActor(){var p=Packet();Entity(p,"train")["maxHp"]=1;var s=Session(p);var end=s.ApplyBasicImpact("end","enemy","train",0);Assert.IsTrue(s.TrainDefeated);var before=s.Capture();Assert.AreSame(end,s.ApplyBasicImpact("end","enemy","train",0));Assert.Throws<InvalidOperationException>(()=>s.ApplyBasicImpact("new","op_mira","enemy",0));Same(before,s.Capture());}
  [TestCase("distance")][TestCase("eligible")][TestCase("expired")][TestCase("wrongKind")][TestCase("ability")]
  public void OriginalGeometryEligibilityAndUnsupportedAbilityNeverPublish(string error){var p=Packet();var g=((JArray)p["geometry"]).Single(x=>(string)x["sourceId"]=="op_mira");if(error=="distance")g["distanceMm"]=1001;if(error=="eligible")g["eligible"]=false;if(error=="expired")g["validUntilTick"]=0;var s=Session(p);var before=s.Capture();Assert.Catch(()=>s.AdvanceAndApplyBasicImpact("bad","op_mira",error=="wrongKind"?"car0":"enemy",1,10000,1,error=="ability"?"ACTIVE":"BASIC"));Same(before,s.Capture());}
  [Test] public void SlotEnvelopeStillLimitsLongRangeWithEligibleRealDistance(){var p=Packet(5);Entity(p,"enemy")["slot"]=4;foreach(var g in (JArray)p["geometry"]){if((string)g["sourceId"]=="enemy")g["sourceSlot"]=4;if((string)g["targetId"]=="enemy")g["targetSlot"]=4;}var s=Session(p);var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>s.ApplyBasicImpact("far","op_mira","enemy",0));Same(before,s.Capture());}
  [Test] public void AdvancePauseSpeedDebtAndReceiptReplayRemainAtomic(){var b=Binding();var s=new BDirectAttackBuffSession(b,10000);s.SetSpeed(4);s.SetPaused(true);var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>s.AdvanceAndApplyBasicImpact("paused","op_mira","enemy",0,10000000,1000));Same(before,s.Capture());s.SetPaused(false);var r=s.AdvanceAndApplyBasicImpact("hit","op_mira","enemy",1800,9000000,1800);Assert.AreEqual(1800,s.Tick);var accepted=s.Capture();Assert.AreSame(r,s.AdvanceAndApplyBasicImpact("hit","op_mira","enemy",1800,9000000,1800));Same(accepted,s.Capture());Same(accepted,BDirectAttackBuffSession.Restore(accepted,b,10000).Capture());Assert.Throws<ArgumentException>(()=>s.AdvanceAndApplyBasicImpact("hit","op_mira","enemy",1800,9000001,1800));Same(accepted,s.Capture());}
  [Test] public void ChildClockCapacityFailureDoesNotCommitCreditOrBuff(){var s=Session(capacity:1);var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>s.AdvanceAndApplyBasicImpact("no-room","op_mira","enemy",1,10000,1));Same(before,s.Capture());Assert.AreEqual(0,(int)s.Capacity()["recorded"]);Assert.AreEqual(0,s.Tick);}
  [Test] public void ArithmeticOverflowAfterAcceptedSourceRollsBackEveryOwner(){var p=Packet();((JArray)Entity(p,"op_mira")["attackSources"]).Add(new JObject{["sourceId"]="LOCAL_OVERFLOW",["ownerId"]="op_mira",["group"]="EQUIPMENT_ATK",["valueBps"]=9007199254740991L});var s=Session(p);var before=s.Capture();Assert.Throws<OverflowException>(()=>s.AdvanceAndApplyBasicImpact("overflow","op_mira","enemy",1,10000,1));Same(before,s.Capture());}
  [TestCase("hash")][TestCase("account")][TestCase("instance")][TestCase("occupant")][TestCase("definition")][TestCase("category")][TestCase("missing")][TestCase("initial")]
  public void BindingBoundaryRejectsMismatchWithoutInferringState(string part){var i=Input();var p=BindingPacket(i);string hash=BDirectAttackInput.Digest(p);if(part=="account")p["departure"]["accountId"]="other";if(part=="instance")p["departure"]["cars"][0]["instanceId"]="other";if(part=="occupant")p["departure"]["cars"][0]["occupant"]["operatorId"]="op_eve";if(part=="definition")p["definitionHash"]="other";if(part=="category")p["targetCategories"][0]["category"]=new JArray("ENEMY","STRUCTURE");if(part=="missing")((JArray)p["targetCategories"]).Clear();if(part=="initial")p["initial"]["cars"][0]["body"]="BROKEN";Assert.Throws<ArgumentException>(()=>new BDirectAttackBuffBinding(i,Defs(),p,part=="hash"?"bad":BDirectAttackInput.Digest(p)));}
  [Test] public void BindingAndReceiptOutputsCannotAlterRunningSource(){var i=Input();var p=BindingPacket(i);var b=new BDirectAttackBuffBinding(i,Defs(),p,BDirectAttackInput.Digest(p));p["targetCategories"][0]["category"]="STRUCTURE";b.Capture()["departure"]["cars"][0]["rank"]=1;var s=new BDirectAttackBuffSession(b,10000);var r=s.ApplyBasicImpact("hit","op_mira","enemy",0);r.BuffSource["damageBps"]=999;s.BuffSnapshot()["actions"][0]["source"]["damageBps"]=999;Assert.AreEqual(3000,Bps(r));}
  [TestCase("hp")][TestCase("clock")][TestCase("next")][TestCase("buff")][TestCase("receipt")][TestCase("binding")][TestCase("journal")][TestCase("schema")]
  public void TamperedCombinedCacheFailsOriginalReplay(string part){var b=Binding();var s=new BDirectAttackBuffSession(b,10000);s.ApplyBasicImpact("hit","op_mira","enemy",0);var cache=s.Capture();if(part=="hp")cache["direct"]["enemies"]["enemy"]["hp"]=1;if(part=="clock")cache["direct"]["clock"]["completedSteps"]=1;if(part=="next")cache["direct"]["next"]["op_mira"]=1;if(part=="buff")cache["buffs"]["actions"][0]["source"]["damageBps"]=999;if(part=="receipt")cache["receipts"][0]["beforeShield"]=999;if(part=="binding")cache["bindingHash"]="changed";if(part=="journal")((JArray)cache["events"]).Add(cache["events"][0].DeepClone());if(part=="schema")cache["version"]=BDirectAttackInput.Version;Assert.Catch(()=>BDirectAttackBuffSession.Restore(cache,b,10000));}
  [Test] public void HistoricalDirectV1CacheRemainsReplayableAndCannotMisreadModifiedChild(){var b=Binding();var old=new BDirectAttackSession(b.Attack,10000);old.ApplyBasicImpact("old","op_mira","enemy",0);Assert.AreEqual(old.CaptureLocal(),BDirectAttackSession.RestoreLocal(old.CaptureLocal(),b.Attack,10000).CaptureLocal());var s=new BDirectAttackBuffSession(b,10000);s.ApplyBasicImpact("new","op_mira","enemy",0);Assert.AreEqual("unity.combat-b.direct-modifier-local.v2",(string)s.Capture()["direct"]["schema"]);Assert.Throws<ArgumentException>(()=>BDirectAttackSession.RestoreLocal(s.Capture()["direct"].ToString(),b.Attack,10000));}
  [Test] public void CargoTargetGetsOnlyItsOwnBodyDefenseAndNoOccupantState(){var p=Packet(5);var s=Session(p,type:"BCB06");var r=s.ApplyBasicImpact("cargo","enemy","car4",0);Assert.IsNull(r.BuffSource);Assert.AreEqual(187,(long)r.Attack.Calculation["effectiveDefense"]["numerator"]);Assert.AreEqual(33,r.Attack.Hp.HpLoss);Assert.AreEqual(967,s.Hp("car4"));Assert.AreEqual(1000,s.Hp("car0"));Assert.AreEqual(1520,s.Hp("op_mira"));var m=BCarriageBuffModel.Restore(s.BuffSnapshot(),Defs());Assert.AreEqual(100,m.Defense(4,"BODY"));Assert.AreEqual(0,m.Defense(4,"OPERATOR"));}
  [Test] public void DistinctUtf16EventIdsCannotCollideOnDerivedBodyStateIdentity(){var p=Packet(5);Entity(p,"car0")["maxHp"]=20;Entity(p,"car1")["maxHp"]=20;var b=Binding(p);var s=new BDirectAttackBuffSession(b,10000);s.ApplyBasicImpact("event_\ud800","enemy","car0",0);s.AdvanceAndApplyBasicImpact("event_\ud801","enemy","car1",2200,22000000,2200);Assert.AreEqual(0,s.Hp("car0"));Assert.AreEqual(0,s.Hp("car1"));Assert.AreEqual(2,(int)s.Capacity()["recorded"]);var restored=BDirectAttackBuffSession.Restore(s.Capture(),b,10000);Same(s.Capture(),restored.Capture());var fresh=s.ApplyBasicImpact("living","op_mira","enemy",2200);var after=restored.ApplyBasicImpact("living","op_mira","enemy",2200);Assert.AreEqual(32,fresh.Attack.BeforeShield);Same(fresh.Attack.Calculation,after.Attack.Calculation);Same(s.Capture(),restored.Capture());}
  [Test] public void FullSharedSourceCapacityRejectsBreakingHitClockAndFreshAttackButReplaysOriginal(){var p=Packet();Entity(p,"enemy")["maxHp"]=1000000;Entity(p,"car0")["maxHp"]=20;foreach(var g in (JArray)p["geometry"])g["validUntilTick"]=5000000;var b=Binding(p);var s=new BDirectAttackBuffSession(b,5000);var first=s.ApplyBasicImpact("a0","op_mira","enemy",0);
   for(int n=1;n<1024;n++)s.AdvanceAndApplyBasicImpact("a"+n,"op_mira","enemy",n*1800L,18000000,1800);Assert.AreEqual(0,(int)s.Capacity()["remaining"]);var before=s.Capture();Assert.Throws<ArgumentException>(()=>s.AdvanceAndApplyBasicImpact("over-source","op_mira","enemy",1024*1800L,18000000,1800));Same(before,s.Capture());Assert.Throws<ArgumentException>(()=>s.AdvanceAndApplyBasicImpact("over-state","enemy","car0",s.Tick+1,10000,1));Same(before,s.Capture());Assert.AreEqual(20,s.Hp("car0"));Assert.AreSame(first,s.ApplyBasicImpact("a0","op_mira","enemy",0));var restored=BDirectAttackBuffSession.Restore(before,b,5000);Same(before,restored.Capture());Assert.Throws<ArgumentException>(()=>restored.AdvanceAndApplyBasicImpact("over-state","enemy","car0",restored.Tick+1,10000,1));Same(before,restored.Capture());}
 }
}
